-- ETL / ELT: MERGE upserts, COPY INTO, staging, streams and tasks
MERGE INTO dim_customer t USING stg_customer s ON t.customer_id = s.customer_id WHEN MATCHED THEN UPDATE SET name = s.name, email = s.email, updated_at = CURRENT_TIMESTAMP() WHEN NOT MATCHED THEN INSERT (customer_id, name, email, updated_at) VALUES (s.customer_id, s.name, s.email, CURRENT_TIMESTAMP());
MERGE INTO target t USING source s ON t.id = s.id WHEN MATCHED AND s.deleted THEN DELETE WHEN MATCHED THEN UPDATE SET val = s.val WHEN NOT MATCHED THEN INSERT (id, val) VALUES (s.id, s.val);
MERGE INTO inventory i USING (SELECT sku, SUM(qty) AS qty FROM shipments GROUP BY sku) s ON i.sku = s.sku WHEN MATCHED THEN UPDATE SET qty = i.qty + s.qty WHEN NOT MATCHED AND s.qty > 0 THEN INSERT VALUES (s.sku, s.qty);
MERGE INTO t USING s ON t.k = s.k WHEN NOT MATCHED THEN INSERT (k, v) VALUES (s.k, s.v);
COPY INTO raw_events FROM @my_stage/events/ FILE_FORMAT = (TYPE = 'JSON') ON_ERROR = 'CONTINUE';
COPY INTO raw_users (id, name) FROM (SELECT $1, $2 FROM @my_stage/users.csv) FILE_FORMAT = (FORMAT_NAME = 'my_csv');
COPY INTO @export_stage/out/ FROM (SELECT * FROM orders WHERE order_date = CURRENT_DATE()) FILE_FORMAT = (TYPE = 'PARQUET') HEADER = TRUE OVERWRITE = TRUE;
COPY INTO mytable FROM @mystage PATTERN = '.*[.]csv' FORCE = TRUE;
INSERT INTO fact_orders SELECT o.id, o.customer_id, o.total, d.date_key FROM stg_orders o JOIN dim_date d ON d.d = o.order_date::date;
INSERT INTO t (a, b) SELECT a, b FROM s WHERE NOT EXISTS (SELECT 1 FROM t WHERE t.a = s.a);
INSERT OVERWRITE INTO report_daily SELECT CURRENT_DATE(), COUNT(*) FROM orders;
INSERT INTO events_json SELECT PARSE_JSON('{"a": 1}');
INSERT INTO t SELECT * FROM TABLE(FLATTEN(input => ARRAY_CONSTRUCT(1, 2, 3)));
CREATE OR REPLACE STREAM orders_stream ON TABLE orders;
CREATE OR REPLACE STREAM s2 ON TABLE orders APPEND_ONLY = TRUE;
SELECT * FROM orders_stream WHERE METADATA$ACTION = 'INSERT';
CREATE OR REPLACE TASK refresh_summary WAREHOUSE = etl_wh SCHEDULE = 'USING CRON 0 * * * * UTC' AS INSERT OVERWRITE INTO summary SELECT region, SUM(amount) FROM sales GROUP BY region;
CREATE TASK t2 WAREHOUSE = w AFTER refresh_summary AS CALL my_proc();
ALTER TASK refresh_summary RESUME;
ALTER TASK refresh_summary SUSPEND;
CREATE OR REPLACE PIPE my_pipe AUTO_INGEST = TRUE AS COPY INTO raw_events FROM @my_stage;
CREATE OR REPLACE DYNAMIC TABLE dt_sales TARGET_LAG = '5 minutes' WAREHOUSE = etl_wh AS SELECT region, SUM(amount) AS total FROM sales GROUP BY region;
CREATE OR REPLACE TABLE dedup_events AS SELECT * FROM raw_events QUALIFY ROW_NUMBER() OVER (PARTITION BY id ORDER BY ts DESC) = 1;
UPDATE target SET status = s.status FROM source s WHERE target.id = s.id AND target.status <> s.status;
DELETE FROM target WHERE id IN (SELECT id FROM source WHERE op = 'D');
LIST @my_stage;
REMOVE @my_stage/old/;
PUT file:///tmp/data.csv @my_stage AUTO_COMPRESS = TRUE;
GET @my_stage/out.csv file:///tmp/;
CALL my_proc(1, 'a');
CALL db.schema.sp_load('2024-01-01'::date);
EXECUTE IMMEDIATE 'SELECT 1';
BEGIN;
INSERT INTO t VALUES (1);
COMMIT;
ROLLBACK;
